"""Shared visual language for the two small web services."""
from flask import render_template_string

def page(title, content):
    return render_template_string('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ title }} · The friendly vote</title><style>
:root{font-family:system-ui,sans-serif;color:#172e39;background:#f4f3ee}*{box-sizing:border-box}body{margin:0}header,main{max-width:960px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d9dfdb}header strong{letter-spacing:-.5px}a{color:#126453;text-underline-offset:4px}main{padding-top:64px;padding-bottom:64px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:2px;color:#526d64;text-transform:uppercase}h1{font-size:clamp(36px,6vw,64px);line-height:1.08;letter-spacing:-2px;margin:16px 0}p{line-height:1.7;color:#52616b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:32px}.card{display:block;width:100%;text-align:left;border:1px solid #d9dfdb;background:white;border-radius:24px;padding:30px;color:inherit;font:inherit;box-shadow:0 8px 28px #173b3210}button.card{cursor:pointer;transition:transform .15s,border-color .15s}button.card:hover{transform:translateY(-4px);border-color:#126453}a:focus-visible,button:focus-visible{outline:3px solid #126453;outline-offset:5px}.icon{font-size:48px}.card h2{font-size:28px;margin:16px 0 8px}.action{display:inline-block;border-radius:100px;padding:12px 20px;background:#126453;color:white;text-decoration:none;font-weight:650;margin-top:16px}.secondary{display:inline-block;margin:20px}.count{font-size:44px;font-weight:750;letter-spacing:-2px}.track{height:12px;border-radius:20px;background:#e8eeea;overflow:hidden;margin:20px 0}.bar{height:100%;background:#126453;border-radius:20px}.dog .bar{background:#b75a30}.notice{padding:20px 24px;background:#e7eee8;border-radius:16px;margin-top:24px}.muted{font-size:14px}@media(max-width:580px){.grid{grid-template-columns:1fr}main{padding-top:36px}.card{padding:24px}header span{display:none}}@media(prefers-reduced-motion:reduce){button.card{transition:none}}
</style></head><body><header><strong>◒ The friendly vote</strong><span>A little choice. A friendly rivalry.</span></header><main>''' + content + '''</main></body></html>''', title=title)
